// Step 1: Validate Task Candidates and Resolve Idempotency Key
const input = $input.first().json;

const userId = input.user_id;
const ingestionId = input.ingestion_id;
const taskCandidates = input.tasks || (input.interpretation && input.interpretation.tasks) || [];

if (!taskCandidates || taskCandidates.length === 0) {
  return [{
    json: {
      ok: false,
      status: 'no_op',
      message: 'No task candidates provided'
    }
  }];
}

const validProcessedTasks = [];
const validationErrors = [];

for (const t of taskCandidates) {
  const timeKnown = Boolean(t.time_known);
  let dueTime = null;
  let dueDate = null;

  // Validate Date: YYYY-MM-DD
  if (t.resolved_date_candidate) {
    const dateStr = String(t.resolved_date_candidate).trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr) || isNaN(Date.parse(dateStr))) {
      validationErrors.push(`Invalid resolved_date_candidate format: ${dateStr}. Expected YYYY-MM-DD.`);
      continue;
    }
    dueDate = dateStr;
  }

  // Validate Time according to time_known rule
  if (timeKnown) {
    if (!t.time_candidate) {
      validationErrors.push('time_known is true but time_candidate is null or empty');
      continue;
    }
    const timeStr = String(t.time_candidate).trim();
    if (timeStr.includes('T') || timeStr.includes('/') || timeStr.length > 8) {
      validationErrors.push(`Invalid time_candidate format: ${timeStr}. Expected HH:MM:SS, got datetime/offset.`);
      continue;
    }
    const timeMatch = timeStr.match(/^([01]\d|2[0-3]):([0-5]\d)(?::([0-5]\d))?$/);
    if (!timeMatch) {
      validationErrors.push(`Invalid time_candidate format: ${timeStr}. Expected HH:MM:SS.`);
      continue;
    }
    dueTime = timeMatch[3] ? `${timeMatch[1]}:${timeMatch[2]}:${timeMatch[3]}` : `${timeMatch[1]}:${timeMatch[2]}:00`;
  } else {
    if (t.time_candidate !== null && t.time_candidate !== undefined && String(t.time_candidate).trim() !== '') {
      validationErrors.push(`time_known is false but time_candidate was provided: ${t.time_candidate}`);
      continue;
    }
    dueTime = null;
  }

  const candidateStr = `${t.title}_${dueDate}_${dueTime}_${timeKnown}_${(t.person_mentions || []).join(',')}`;
  let hash = 0;
  for (let i = 0; i < candidateStr.length; i++) {
    hash = ((hash << 5) - hash) + candidateStr.charCodeAt(i);
    hash |= 0;
  }
  const candidateHash = Math.abs(hash).toString(16);
  const idempotencyKey = `task:auto:${ingestionId}:${candidateHash}`;

  validProcessedTasks.push({
    operation: t.operation || 'create',
    title: t.title,
    description: t.description || null,
    resolved_date_candidate: dueDate,
    due_date: dueDate,
    due_time: dueTime,
    time_candidate: dueTime,
    time_known: timeKnown,
    priority: t.priority || 'normal',
    priority_source: t.priority_source || 'ai',
    status: t.status_candidate || 'pending',
    status_candidate: t.status_candidate || 'pending',
    person_mentions: t.person_mentions || [],
    idempotency_key: idempotencyKey,
    requires_clarification: Boolean(t.requires_clarification)
  });
}

if (validProcessedTasks.length === 0) {
  return [{
    json: {
      ok: false,
      status: 'validation_error',
      errors: validationErrors,
      message: 'All task candidates failed deterministic temporal validation'
    }
  }];
}

return [{
  json: {
    ...input,
    user_id: userId,
    ingestion_id: ingestionId,
    processed_tasks: validProcessedTasks
  }
}];

const req = $('Validate Task Candidates').first().json;
const resRaw = $input.first().json.res;
const res = typeof resRaw === 'string' ? JSON.parse(resRaw) : resRaw;

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: req.correlation_id,
    data: {
      ...res,
      task_count: (res.task_ids || []).length,
      reminder_status: 'DEFERRED_PHASE_DEPENDENCY_F2'
    }
  }
}];
